\end{align*}

Similarly, we have   $$ a-t = \frac{(m-q)(mnq-mnr+mn+mqr-2mq-nqr+qr)}{(m+q)(mn-m-n-qr+q+r)} $$    $$ \overline{a-t}=\frac{(q-m)(r-q+qr+n-2nr-m+mn)}{(q+m)(rq-nrq-mrq-mn+mnr+mnq)} $$  Also, note that   $$ a-c=\frac{2mq}{m+q}-\frac{2nr}{n+r}=2\cdot\frac{mq(n+r)-nr(m+q)}{(m+q)(n+r)}=2\cdot\frac{m+q-n-r}{(m+q)(n+r)} $$    $$ \overline{a-c}=\frac{2}{m+q}-\frac{2}{n+r}=2\cdot\frac{n+r-m-q}{(m+q)(r+n)} $$  Hence, we have the following:   $$ (a-c)=-\overline{\left(a-c\right)} $$  \begin{align*}
    \frac{t-c}{\overline{\left(a-t\right)}} &= \frac{\frac{(n-r)(-mnq+mnr+mn-mqr+nqr-2nr+qr)}{(r+n)(m+n-r-q-mn+rq)}}{\frac{(q-m)(r-q+qr+n-2nr-m+mn)}{(q+m)(rq-nrq-mrq-mn+mnr+mnq)}} 
    &=\frac{\frac{(n-r)(-m-q+n+r+mn-2nr+qr)}{(r+n)(m+n-r-q-mn+rq)}}{\frac{(q-m)(r-q+qr+n-2nr-m+mn)}{(q+m)(rq-nrq-mrq-mn+mnr+mnq)}} 
    &= \frac{(n-r)(q+m)(rq-nrq-mrq-mn+mnr+mnq)}{(q-m)(r+n)(m+n-r-q-mn+rq)}
\end{align*}


\begin{align*}
     \frac{a-t}{\overline{\left(t-c\right)}} &= \frac{\frac{(m-q)(mnq-mnr+mn+mqr-2mq-nqr+qr)}{(m+q)(mn-m-n-qr+q+r)}}{\frac{(r-n)(-r+q+qr-n+m-2mq+mn)}{(r+n)(nqr+mqr-mnq-mnr-qr+mn)}} 
     &= \frac{\frac{(m-q)(m+q-n-r+mn-2mq+qr)}{(m+q)(mn-m-n-qr+q+r)}}{\frac{(r-n)(-r+q+qr-n+m-2mq+mn)}{(r+n)(nqr+mqr-mnq-mnr-qr+mn)}} 
     &= \frac{(m-q)(r+n)(nqr+mqr-mnq-mnr-qr+mn)}{(r-n)(m+q)(mn-m-n-qr+q+r)} 
     &=\frac{(q-m)(r+n)(-nqr-mqr+mnq+mnr+qr-mn)}{(n-r)(m+q)(m+n-q-r+qr-mn)}
\end{align*}

\begin{align*}
    p-t &=2\cdot\frac{mn-rq+rq(m+n)-mn(r+q)}{m+n-r-q+rq(m+n)-mn(r+q)}-\frac{mn-rq+rq(m+n)-mn(r+q)}{m+n-r-q-mn+rq}
    &=\frac{(mn-rq+rq(m+n)-mn(r+q))\cdot X}{(m+n-r-q+rq(m+n)-mn(r+q))(m+n-r-q-mn+rq)}
\end{align*} where we have substituted   $$ X=m+n-r-q-2mn+2rq-rq(m+n)+mn(r+q). $$  We will now calculate  $\overline{p-t}.$  Firstly, we have 
\begin{align*}
   \overline{X} &= \frac{1}{m}+\frac{1}{n}-\frac{1}{r}-\frac{1}{q}-\frac{2}{mn}+\frac{2}{rq} -\frac{1}{rqm}-\frac{1}{rqn}+\frac{1}{mnr}+\frac{1}{mnq} 
   &= \frac{nrq+mrq-mnq-mnr-2rq+2mn-n-m+r+q}{mnqr}
\end{align*}

The conjugate of the bracket in the numerator is 
\begin{align*}
    (1)  &= \frac{1}{mn}-\frac{1}{rq}+\frac{1}{rqm}+\frac{1}{rqn}-\frac{1}{mnr}-\frac{1}{mnq} 
    &= \frac{rq-mn+n+m-q-r}{mnqr}
\end{align*}

The conjugate of the denominator is 
\begin{align*}
    (2) &= \left(\frac{1}{m}+\frac{1}{n}-\frac{1}{r}-\frac{1}{q}+\frac{1}{rqm}+\frac{1}{rqn}-\frac{1}{mnr}-\frac{1}{mnq}\right)\left(\frac{1}{m}+\frac{1}{n}-\frac{1}{r}-\frac{1}{q}-\frac{1}{mn}+\frac{1}{rq}\right) 
    &= \frac{(nrq+mrq-mnq-mnr+n+m-r-q)(nrq+mrq-mnq-mnr-rq+mn)}{(mnrq)^2}
\end{align*}

Hence,   $$ \overline{p-t}=\frac{(nrq+mrq-mnq-mnr-2rq+2mn-n-m+r+q)(rq-mn+n+m-q-r)}{(nrq+mrq-mnq-mnr+n+m-r-q)(nrq+mrq-mnq-mnr-rq+mn)} $$   and thus   $$ \frac{p-t}{\overline{\left(p-t\right)}}=-\frac{(rq-nrq-mrq-mn+mnr+mnq)^2}{(m+n-mn+rq-r-q)^2} $$  We will be done if we prove   $$ \frac{(a-c)(p-t)}{(t-c)(a-t)}=\overline{\left(\frac{(a-c)(p-t)}{(t-c)(a-t)}\right)} \iff\frac{p-t}{\overline{\left(p-t\right)}}=\frac{\overline{\left(a-c\right)}}{a-c}\cdot\frac{t-c}{\overline{\left(a-t\right)}}\cdot\frac{a-t}{\overline{\left(t-c\right)}}\iff $$     $$ \iff \frac{p-t}{\overline{\left(p-t\right)}}=-\frac{(rq-nrq-mrq-mn+mnr+mnq)^2}{(m+n-mn+rq-r-q)^2}, $$   which is true, so we are done.

